{"name":"typec_partner_unlink_device","qualified_name":"workspace-linux.drivers.usb.typec.class.typec_partner_unlink_device","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/class.c","start_line":906,"end_line":913,"source":"static void typec_partner_unlink_device(struct typec_partner *partner, struct device *dev)
