{"name":"typec_partner_attach","qualified_name":"workspace-linux.drivers.usb.typec.class.typec_partner_attach","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/class.c","start_line":2144,"end_line":2167,"source":"static void typec_partner_attach(struct typec_connector *con, struct device *dev)
