{"name":"kernfs_remove_by_name_ns","qualified_name":"workspace-linux.fs.kernfs.dir.kernfs_remove_by_name_ns","label":"Function","file_path":"/workspace/linux/fs/kernfs/dir.c","start_line":1724,"end_line":1752,"source":"int kernfs_remove_by_name_ns(struct kernfs_node *parent, const char *name,
			     const struct ns_common *ns)
{
	struct kernfs_node *kn;
	struct kernfs_root *root;

	if (!parent) {
		WARN(1, KERN_WARNING "kernfs: can not remove '%s', no directory\n",
			name);
		return -ENOENT;
	}

	root = kernfs_root(parent);
	down_write(&root->kernfs_rwsem);

	kn = kernfs_find_ns(parent, name, ns);
	if (kn) {
		kernfs_get(kn);
		__kernfs_remove(kn);
		kernfs_put(kn);
	}

	up_write(&root->kernfs_rwsem);

	if (kn)
		return 0;
	else
		return -ENOENT;
}
